// Combina items RSS (con category) + entradas del log (isLogEntry=true)
const items = $input.all();

const logLinks = items
  .filter(i => i.json.isLogEntry === true)
  .map(i => i.json.Link);

const rssItems = items.filter(i => !i.json.isLogEntry);

const freshItems = rssItems.filter(i => !logLinks.includes(i.json.link));

if (freshItems.length === 0) {
  return [{ json: { found: false } }];
}

const chosen = freshItems[Math.floor(Math.random() * freshItems.length)];

return [{
  json: {
    found: true,
    title: chosen.json.title || '',
    link: chosen.json.link || '',
    description: (chosen.json.contentSnippet || chosen.json.content || '').toString().substring(0, 500),
    category: chosen.json.category || 'General'
  }
}];

