const category = $('Select New Topic').item.json.category;
const postText = $('Final Post Text').item.json.content;

// Estilo base más corto (menos tokens = URL final más corta y segura)
const baseStyle = "digital matte painting, Unreal Engine 5 render, cinematic lighting, volumetric fog, dramatic depth of field, dynamic low-angle camera, rich color grading, high contrast, ultra detailed, 8k";

// Escenas acortadas — mismo concepto, menos palabras
const categoryScenes = {
  "Ciberseguridad": [
    "Hand typing on keyboard in dark room, red terminal warnings on monitors, cinematic blue-red lighting",
    "Glowing digital padlock shattering into binary code, deep navy background, dramatic lighting"
  ],
  "Infraestructura": [
    "Isometric data center with glowing server racks, streams of light, night city skyline",
    "Symmetrical corridor of server racks, blue LED lights, silhouette figure walking away"
  ],
  "IA": [
    "Glowing neural network sphere made of light particles, floating in dark space, purple-cyan gradient",
    "Human silhouette dissolving into glowing data particles, minimalist dark background"
  ],
  "Hardening": [
    "Isometric stone castle with glowing circuit patterns, translucent digital shield dome, dusk sky",
    "Interlocking metal gears and circuit boards forming barrier, dramatic side lighting"
  ]
};

const scenes = categoryScenes[category] || categoryScenes["Ciberseguridad"];
const chosenScene = scenes[Math.floor(Math.random() * scenes.length)];
const imagePrompt = `${chosenScene}, ${baseStyle}`;

const availableModels = ["flux", "flux-realism", "flux-3d", "turbo"];
const chosenModel = availableModels[Math.floor(Math.random() * availableModels.length)];
const seed = Math.floor(Math.random() * 1000000);

const cleanText = postText
  .replace(/#\w+/g, '')
  .replace(/[\u{1F300}-\u{1FAFF}]/gu, '')
  .trim();

let headline = cleanText.split(/[.!?\n]/)[0]
  .replace(/[^a-zA-ZÀ-ÿ0-9 ]/g, '')
  .trim()
  .toUpperCase();

const words = headline.split(/\s+/).slice(0, 5);
headline = words.join(' ');
const headlineUrlSafe = headline.replace(/\s+/g, '%20');

return [{
  json: {
    ...$('Final Post Text').item.json,
    imagePrompt: imagePrompt,
    imageSeed: seed,
    imageModel: chosenModel,
    headlineText: headlineUrlSafe
  }
}];

